INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `icon`, `color`, `isAdult`, `isActive`, `sortOrder`, `source`, `createdAt`, `updatedAt`) VALUES
('cat-amistad', 'Amistad', 'amistad', 'Comunidades para hacer amigos de verdad: planes de fin de semana, charla diaria y gente nueva de tu ciudad o de todo el mundo hispanohablante.', '🤝', 'emerald', 0, 1, 100, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-arte', 'Arte y Diseño', 'arte', 'Ilustración, fotografía analógica, dibujo y tatuajes. Comparte tu portafolio, recibe feedback y participa en retos creativos semanales.', '🎨', 'fuchsia', 0, 1, 230, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-cine', 'Cine y TV', 'cine', 'Recomendaciones de películas y series, estrenos semanales, terror, Marvel y cine latinoamericano. Comparte qué ver y debate finales sin spoiler.', '🎬', 'rose', 0, 1, 150, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-citas-18', 'Citas y Encuentros 18+', 'citas-18', 'Comunidades 18+ para conocer gente nueva de tu ciudad con respeto y claridad. Solo adultos: verificación de edad activada.', '💋', 'rose', 1, 1, 900, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-cocina', 'Cocina', 'cocina', 'Recetas caseras de cada país: cocina mexicana, peruana, asados argentinos, tapas españolas y arepas colombianas. Comparte tus trucos de cocina.', '🍳', 'orange', 0, 1, 160, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-compraventa', 'Compra y Venta', 'compraventa', 'Marketplaces locales por ciudad: tecnología, usados, trueques y segunda mano. Vende y compra con gente de tu zona, sin intermediarios.', '🛒', 'stone', 0, 1, 210, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-deportes', 'Deportes', 'deportes', 'Fútbol de liga, béisbol caribeño, ciclismo y cada pasión deportiva en español. Resultados en vivo, debates y fantasy con fans de tu equipo.', '⚽', 'lime', 0, 1, 130, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-educacion', 'Educación', 'educacion', 'Grupos de estudio universitario, apuntes, becas y preparación de exámenes. Ayuda mutua entre estudiantes de toda Hispanoamérica y España.', '📚', 'teal', 0, 1, 170, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-empleo', 'Empleo', 'empleo', 'Bolsas de empleo por país con vacantes verificadas a diario: trabajo remoto, presencial y por proyecto. Publica y encuentra oportunidades serias.', '💼', 'slate', 0, 1, 240, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-entretenimiento', 'Entretenimiento', 'entretenimiento', 'Trivia nocturna, karaoke por notas de voz, farándula y comunidades random para matar el aburrimiento con gente divertida.', '🎉', 'pink', 0, 1, 290, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-exclusivo-18', 'Contenido Exclusivo 18+', 'contenido-exclusivo-18', 'Comunidades premium 18+ con acceso limitado y moderación estricta. Contenido exclusivo para adultos verificados.', '🔥', 'red', 1, 1, 910, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-humor', 'Humor', 'humor', 'Los mejores grupos de memes y humor por país: argentinos, mexicanos, chilenos y peruanos riéndose de todo con contenido fresco a diario.', '😂', 'yellow', 0, 1, 140, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-idiomas', 'Idiomas', 'idiomas', 'Practica inglés, francés, italiano e intercambios de idiomas con nativos. Grupos de conversación real por notas de voz, sin clases aburridas.', '🗣️', 'sky', 0, 1, 220, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-mascotas', 'Mascotas', 'mascotas', 'Comunidades de amantes de perros y gatos: adopción responsable, consejos veterinarios y rescate de callejeritos. Comparte fotos y experiencia.', '🐶', 'amber', 0, 1, 180, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-musica', 'Música', 'musica', 'Comunidades de fans por género y país: rock, reggaetón clásico, salsa, flamenco, corridos y más. Descubre música nueva y debate con gente con tu mismo gusto.', '🎵', 'violet', 0, 1, 120, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-negocios', 'Negocios', 'negocios', 'Emprendimiento, e-commerce, freelance y marketing digital en español. Comparte tu proyecto, consigue feedback y aprende de otros emprendedores.', '💼', 'green', 0, 1, 200, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-noticias', 'Noticias', 'noticias', 'Resúmenes diarios de actualidad de tu país y del mundo hispano. Debate con perspectiva y mantente informado sin ruido ni fake news.', '📰', 'stone', 0, 1, 250, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-religion', 'Fe y Reflexión', 'religion', 'Comunidades de oración, reflexión diaria y apoyo espiritual. Palabra del día, peticiones de oración y espacios respetuosos de fe.', '🙏', 'violet', 0, 1, 260, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-salud', 'Salud y Bienestar', 'salud', 'Gimnasio, running, yoga y salud mental. Comparte rutinas, progreso y hábitos con comunidades activas que te acompañan día a día.', '💪', 'emerald', 0, 1, 270, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-tecnologia', 'Tecnología', 'tecnologia', 'Grupos de programación, inteligencia artificial, software libre, gadgets y soporte técnico en español. Comparte dudas, recursos y novedades del sector.', '💻', 'sky', 0, 1, 110, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-viajes', 'Viajes', 'viajes', 'Mochileros, road trips y rutas por Latinoamérica y Europa. Presupuestos, destinos ocultos y consejos de viajeros con experiencia real.', '✈️', 'cyan', 0, 1, 190, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27'),
('cat-videojuegos', 'Videojuegos', 'videojuegos', 'Encuentra squad para Free Fire, EA FC, Valorant y Minecraft. Comunidades gamer por país: torneos, clips y teammates serios.', '🎮', 'purple', 0, 1, 280, 'seed', '2026-10-13 21:32:27', '2026-10-13 21:32:27')
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `slug` = VALUES(`slug`), `description` = VALUES(`description`), `icon` = VALUES(`icon`), `color` = VALUES(`color`), `isAdult` = VALUES(`isAdult`), `isActive` = VALUES(`isActive`), `sortOrder` = VALUES(`sortOrder`), `source` = VALUES(`source`), `createdAt` = VALUES(`createdAt`), `updatedAt` = VALUES(`updatedAt`);

