CREATE TABLE IF NOT EXISTS `groups_queue` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `groupName` varchar(255) NOT NULL,
  `joinLink` varchar(512) NOT NULL,
  `description` text NOT NULL,
  `category` varchar(255) NOT NULL DEFAULT '',
  `country` varchar(255) NOT NULL DEFAULT '',
  `city` varchar(255) DEFAULT NULL,
  `keywords` text NOT NULL,
  `tags` text NOT NULL,
  `profileImage` varchar(512) DEFAULT NULL,
  `uploaderId` varchar(191) DEFAULT NULL,
  `isAdult` tinyint(1) NOT NULL DEFAULT 0,
  `language` varchar(64) NOT NULL DEFAULT 'Espanol',
  `addedAt` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_gq_addedAt` (`addedAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- (no rows)

-- ---------------------------------------------------------------------------
-- Table: blog_posts
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `blog_posts` (
  `id` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `title` varchar(255) NOT NULL,
  `excerpt` varchar(500) DEFAULT NULL,
  `content` mediumtext NOT NULL,
  `coverEmoji` varchar(16) DEFAULT '?',
  `tags` varchar(500) DEFAULT NULL,
  `authorName` varchar(120) DEFAULT 'Equipo ConectaGrupos',
  `status` varchar(32) NOT NULL DEFAULT 'draft',
  `metaTitle` varchar(255) DEFAULT NULL,
  `metaDescription` varchar(500) DEFAULT NULL,
  `readingMinutes` int(11) NOT NULL DEFAULT 4,
  `views` int(11) NOT NULL DEFAULT 0,
  `publishedAt` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT current_timestamp(),
  `updatedAt` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_blog_status_published` (`status`,`publishedAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `blog_posts` (`id`, `slug`, `title`, `excerpt`, `content`, `coverEmoji`, `tags`, `authorName`, `status`, `metaTitle`, `metaDescription`, `readingMinutes`, `views`, `publishedAt`, `createdAt`, `updatedAt`) VALUES
('post-001', 'como-encontrar-grupos-de-whatsapp-seguros-2026', 'Cómo encontrar grupos de WhatsApp seguros en 2026: guía completa', 'Aprende a identificar comunidades fiables de WhatsApp, evitar estafas y enlaces caducados, y unirte a grupos activos de verdad. La guía de seguridad que usamos a diario en Grupos Hoy.', '## Por qué importa elegir bien el grupo\n\nUnirse a un grupo de WhatsApp es de las cosas más fáciles del mundo: un clic en el enlace de invitación y ya estás dentro. Lo difícil es salir bien parado. En 2026 siguen circulando comunidades abandonadas, enlaces caducados y, en el peor de los casos, grupos usados para estafas o spam masivo.\n\nEsta guía resume el método que usamos a diario en [Grupos Hoy](/) para revisar los grupos que publicamos: los mismos criterios que puedes aplicar tú antes de dar el salto.\n\n## 1. Comprueba que el enlace está vivo\n\nEl primer filtro es el más obvio y el más ignorado: **el enlace de invitación debe funcionar**. WhatsApp muestra un aviso claro («Este enlace de invitación ya no es válido») cuando el grupo se llenó, el administrador revocó el enlace o el grupo se eliminó.\n\nEn nuestro directorio cada grupo pasa por una verificación periódica del enlace y verás el estado en la propia ficha. Si un enlace falla, puedes [reportar el grupo](/reportar-grupo) y lo revisamos.\n\n## 2. Mira el tamaño, pero no te obsesiones\n\n- **Grupos pequeños (menos de 50 miembros):** conversaciones cercanas, casi todo el mundo participa. Perfecto para temas locales o nichos.\n- **Grupos medianos (50–256):** el punto dulce para la mayoría de temas: hay vida pero aún se puede seguir el hilo.\n- **Grupos grandes (más de 256):** mucho movimiento y contenido, pero también más ruido. Activa silencios y revisa el historial antes de escribir.\n\n## 3. Revisa la descripción y las normas\n\nUn grupo cuidado casi siempre publica normas claras: qué se puede compartir, horarios, idioma y qué pasa si haces spam. Si la descripción es vaga o directamente no existe, alza una ceja. Los grupos del [directorio](/#grupos) incluyen descripción, categoría y país para que decidas con contexto.\n\n## 4. Fíjate en la actividad reciente\n\nNo hay nada más frustrante que entrar a un grupo donde el último mensaje es de hace tres meses. Antes de unirte:\n\n1. Busca la fecha del último mensaje visible.\n2. Comprueba si el administrador participa.\n3. Observa la proporción de enlaces: si el 90% de los mensajes son promociones, es spam con disfraz.\n\nEn [Grupos Hoy](/populares) marcamos los grupos con más movimiento reciente para que no pierdas el tiempo.\n\n## 5. Cuida tu privacidad desde el primer día\n\nCuando entras a un grupo, tu número de teléfono es visible para todos los miembros. Algunos consejos rápidos:\n\n- Usa la función de **WhatsApp Business** o un número secundario si vas a participar en muchos grupos públicos.\n- Nunca compartas datos bancarios, contraseñas ni documentos personales en un grupo.\n- Configura tu foto de perfil como visible «solo para mis contactos» si no quieres que extraños la vean.\n- Si alguien te escribe en privado sin haber hablado antes en el grupo, desconfía: es el patrón clásico del estafador.\n\n## 6. Aprovecha las categorías y los países\n\nLa forma más rápida de encontrar comunidades que valgan la pena es filtrar por tema y región. No es lo mismo un grupo de fútbol de tu ciudad que uno genérico internacional: los horarios, la jerga y las costumbres cambian.\n\nExplora por [categorías](/categorias) (humor, tecnología, música, estudio…) o por [país](/paises) para dar con grupos donde la conversación encaja contigo.\n\n## 7. Salir de un grupo no es un drama\n\nSi el grupo no es lo que esperabas, salir es tan simple como pulsar «Salir del grupo» en la propia conversación. No se notifica a los demás miembros y no tienes que dar explicaciones. Si el contenido era inadecuado, además puedes reportarlo a WhatsApp desde el propio chat (Toque y mantener > Reportar).\n\n## Resumen: checklist antes de unirte\n\n- ✅ El enlace funciona y el grupo tiene miembros activos.\n- ✅ La descripción explica el tema y las normas.\n- ✅ El tamaño encaja con lo que buscas (íntimo, equilibrado o masivo).\n- ✅ Es de tu país o tu zona horaria.\n- ✅ No te piden datos personales para «entrar» (ningún grupo legítimo lo hace).\n\nSi administras una comunidad y quieres que aparezca en el directorio, puedes [enviar tu grupo](/agregar-grupo) gratis: lo revisamos en menos de 24 horas y queda disponible para miles de hispanohablantes.\n\n¡Feliz búsqueda!', '🛡️', '["whatsapp", "seguridad", "guias", "consejos"]', 'Antonio C.', 'published', 'Grupos de WhatsApp seguros en 2026: guía completa', 'Aprende a identificar comunidades fiables de WhatsApp, evitar estafas y enlaces caducados, y unirte solo a grupos activos y verificados.', 6, 214, '2026-10-01 21:32:27', '2026-09-29 21:32:27', '2026-10-13 21:39:36')
ON DUPLICATE KEY UPDATE `slug` = VALUES(`slug`), `title` = VALUES(`title`), `excerpt` = VALUES(`excerpt`), `content` = VALUES(`content`), `coverEmoji` = VALUES(`coverEmoji`), `tags` = VALUES(`tags`), `authorName` = VALUES(`authorName`), `status` = VALUES(`status`), `metaTitle` = VALUES(`metaTitle`), `metaDescription` = VALUES(`metaDescription`), `readingMinutes` = VALUES(`readingMinutes`), `views` = VALUES(`views`), `publishedAt` = VALUES(`publishedAt`), `createdAt` = VALUES(`createdAt`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `blog_posts` (`id`, `slug`, `title`, `excerpt`, `content`, `coverEmoji`, `tags`, `authorName`, `status`, `metaTitle`, `metaDescription`, `readingMinutes`, `views`, `publishedAt`, `createdAt`, `updatedAt`) VALUES
('post-002', 'como-moderar-un-grupo-de-whatsapp-exitoso', 'Cómo moderar un grupo de WhatsApp exitoso: 6 reglas de oro para admins', 'Las comunidades que sobreviven años no son las más grandes: son las mejor moderadas. Seis reglas de oro para administradores, extraídas de revisar cientos de grupos hispanos.', '## ¿Por qué moderar bien cambia todo\n\nUn grupo de WhatsApp puede tener 500 miembros y estar muerto, o 40 y ser imparable. La diferencia casi nunca es el tema: es cómo se modera. Después de revisar cientos de comunidades para [Grupos Hoy](/), la conclusión es clara: los grupos que sobreviven años comparten las mismas reglas básicas.\n\nEsta guía resume el método que aplicamos al curar comunidades en nuestro [directorio de categorías](/categorias): criterios concretos que puedes copiar para tu propio grupo desde hoy.\n\n## 1. Escribe normas desde el día uno\n\nLas normas no ahuyentan a la gente: ahuyentan al spam. Un grupo sin reglas se llena de cadenas, estafas y publicidad en semanas. Con publicar tres reglas simples basta:\n\n- **Tema:** qué se habla y qué no.\n- **Formato:** cómo se publican enlaces, ofertas o imágenes.\n- **Respeto:** sin insultos, sin acoso, sin spam.\n\nFíjalas en la descripción del grupo: cada nuevo miembro las verá al entrar sin necesidad de repetirlas.\n\n## 2. Ten al menos dos administradores\n\nEl admin único es el punto débil de cualquier comunidad: se va de viaje, cambia de número y el grupo queda huérfano. Dos o tres admins activos garantizan que siempre haya alguien con permisos para frenar un spam masivo a las 3 AM.\n\nEn las comunidades que publicamos pedimos moderación activa comprobada: un grupo sin admins presentes acaba fuera del [directorio](/).\n\n## 3. Controla quién entra y con qué fin\n\nEl enlace de invitación es la puerta de tu casa. Si lo compartes públicamente sin control, entra de todo. Opciones que funcionan:\n\n- **Enlace con aprobación:** WhatsApp permite aprobar cada solicitud de ingreso.\n- **Rotar el enlace:** si detectas spam masivo, revoca el enlace antiguo y genera uno nuevo.\n- **Presentación al entrar:** pedir nombre, ciudad e interés real filtra a los spammers.\n\nSi tu grupo es de un país concreto, revisa nuestra sección de [grupos por país](/paises) para ver cómo se organizan las comunidades más activas.\n\n## 4. Silencia el ruido, no a la gente\n\nWhatsApp permite restringir quién puede enviar mensajes y cada cuánto. Úsalo con cabeza: un grupo donde solo hablan tres se convierte en canal, y los canales mueren. Mejor alternar: semanas de conversación libre y momentos de anuncios controlados.\n\n## 5. Cuida el nombre y la descripción del grupo\n\nEl nombre es el SEO de WhatsApp: «Planes fin de semana CDMX» atrae a quien busca exactamente eso; «Grupo de Juanjo» no. La descripción completa con tema, zona y normas ayuda a los nuevos a entender el grupo en cinco segundos.\n\n## 6. Renueva lo que no funciona\n\nUn grupo se muere de a poco: primero se van los que preguntan, luego los que contestan, y quedan solo los memes reciclados. Si tu comunidad lleva meses sin actividad real, considera cerrarla y abrir una enfocada: la gente agradece grupos vivos antes que grupos viejos.\n\n## Resumen: el decálogo del buen admin\n\n- ✅ Normas claras y visibles desde el inicio.\n- ✅ Dos admins mínimo, activos y coordinados.\n- ✅ Control de ingresos y enlace revocable.\n- ✅ Nombre y descripción que explican el grupo.\n- ✅ Actividad real: si se apaga, mejor renovar que abandonar.\n\nSi administras una comunidad así, puedes [enviar tu grupo](/agregar-grupo) gratis y la revisamos para incluirla en el directorio. Y si buscas comunidades bien moderadas para unirte, empieza por [las más populares](/populares) del momento.', '👑', '["whatsapp", "moderacion", "admins", "consejos"]', 'Antonio C.', 'published', 'Cómo moderar un grupo de WhatsApp exitoso: 6 reglas de oro', 'Seis reglas de oro para moderar grupos de WhatsApp: normas, admins, control de ingresos y moderación que mantiene la comunidad viva durante años.', 5, 260, '2026-10-10 21:32:27', '2026-10-08 21:32:27', '2026-10-13 21:32:27')
