CREATE TABLE IF NOT EXISTS `entity_intros` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `entityType` varchar(32) NOT NULL,
  `entityName` varchar(255) NOT NULL,
  `customTitle` varchar(512) DEFAULT NULL,
  `customHeroDesc` text DEFAULT NULL,
  `customIntro` text DEFAULT NULL,
  `updatedAt` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_intro_type_name` (`entityType`,`entityName`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(1, 'country', 'Argentina', NULL, NULL, 'El mate gira de mano en mano y el teléfono no para de vibrar. En Argentina el grupo de la cancha suena antes, durante y después del partido: la charla del Superclásico arranca el viernes y sigue hasta el lunes. Los audios son largos y apasionados, como una mesa de bar. El domingo, mientras se hace el asado, alguien ya mandó la foto del corte. Entre semana, el grupo del trabajo mezcla chistes, quejas del clima y la lista de quién faltó a la quinta.\n\n¿Qué abunda por acá? Grupos de fútbol del torneo local y de la Sele, compra-venta del barrio, grupos de la facultad para organizar entregas y el fútbol de los viernes. También los de memes argentinos, que se reenvían antes del primer café. En Grupos Hoy podés filtrar por Argentina y elegir la categoría después. La lista queda solo con grupos del país, cada uno con su tema a la vista.\n\nUn consejo de alguien que vio de todo: si llega una cadena que dice «reenviá esto o WhatsApp empezará a cobrar», no le creas. WhatsApp no cobra por usar el servicio y no borra cuentas por no reenviar mensajes. Respirá, borrá y seguí con tu día. Lo mismo con las cadenas de la suerte: no pasa nada si no las mandás, de verdad. Los admins argentinos ya las conocen de memoria.\n\n¿Administrás un grupo argentino? Pasalo por «Enviar un grupo» y en un rato queda publicado para gente de todo el país. Es gratis, toma lo mismo que cebar unos mates, y le sirve a otro pibe que anda buscando justo lo que vos armaste.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(2, 'country', 'Bolivia', NULL, NULL, 'La mañana paceña empieza arriba, en el teleférico, con el grupo de la familia ya lleno de mensajes. Alguien avisa que llega tarde porque la línea de Mi Teleférico hizo fila. Alguien más manda el «buenos días» de siempre con flores y taza de café. La salteña del desayuno aparece en foto antes que en la boca. Y cuando llega el Carnaval de Oruro, el chat explota con videos de la entrada y planes para ver la comparsa en persona.\n\nPor acá sobran los grupos parroquiales y los universitarios, y también los del clásico paceño de fútbol. En la compra-venta se ofrece de todo, y los chistes del altiplano se comparten a toda hora. Tampoco faltan los grupos de trabajo, donde se avisan turnos, ferias y días de pago. Si buscas grupos de Bolivia sin revolver resultados de otros países, Grupos Hoy te lo pone fácil. El filtro de país está a un toque: marcas Bolivia y ya está.\n\nUn detalle que ayuda: al entrar a un grupo grande, mira un rato antes de escribir. Fíjate cómo saluda la gente, qué temas se permiten y a qué hora se calla el chat. Y si las imágenes de «buenos días» te llenan la galería, apaga la descarga automática en los ajustes de WhatsApp. El cariño queda igual y el teléfono respira.\n\nSi tienes un grupo boliviano bien llevado, con reglas claras y admin despierto, publicarlo toma unos minutos. Entra a «Enviar un grupo», completa los datos y deja que lo encuentre gente de La Paz, El Alto, Santa Cruz y Cochabamba.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(3, 'country', 'Chile', NULL, NULL, 'Cuando tiembla en Santiago, el primer lugar donde todos se enteran es el grupo de vecinos. En Chile los grupos funcionan como red de emergencia y de cariño a la vez. Avisan del temblor y del corte de luz, y también arman la once del domingo. Porque la once no es solo té con pan: es palta, quesillo y conversa. Y de fútbol ni hablar: entre Colo Colo y la U hay grupos que no descansan ni en enero.\n\n¿Qué vas a encontrar? Grupos de hinchada para discutir el campeonato y de trekking para subir la cordillera en primavera. También compra-venta del barrio, grupos de apoderados del colegio y memes que solo se entienden con un «cachai» por medio. Grupos Hoy tiene un filtro para Chile: lo activas y la lista queda solo con comunidades del país, sin mezclar nada de afuera.\n\nOjo con los rumores: después de un temblor fuerte siempre circula el falso aviso de evacuación o la alarma de maremoto que nadie confirmó. Antes de reenviar algo así, frena y revisa un canal oficial. Un mensaje equivocado a medianoche asusta a la cuadra entera. En los grupos de vecinos, la calma vale oro.\n\n¿Y si tu grupo chileno no aparece acá? Súbelo. La sección «Enviar un grupo» está abierta para compartir tu comunidad: la del edificio, la del curso o la de la barra del club. Publicar no cuesta nada y toma menos que ir por la once. Además, cada enlace pasa por revisión humana, para que nadie pierda el tiempo con grupos muertos.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(4, 'country', 'Colombia', NULL, NULL, 'El celular de un colombiano descansa poco. Hay un grupo para el trabajo, otro para la familia, otro para el barrio y uno más para los amigos de siempre. La conversa arranca con un «¿qué más pues?» y ya no para. En Bogotá se arregla la salida al cine por chat; en Medellín, el parcero organiza el futbol de los sábados. Y en diciembre los audios de la Novena se multiplican, con villancicos, buñuelos y natilla por delante.\n\nLos grupos colombianos más buscados: fútbol de la Sele y el clásico paisa, compra-venta con ofertas de todo tipo y los universitarios para trabajos y apuntes. También abundan los memes que mezclan humor costeño, paisa y rolo. En los barrios, los grupos de vecinos avisan desde la obra de la esquina hasta el mercado del sábado. En Grupos Hoy puedes marcar Colombia y quedarte solo con grupos de esta tierra, sin ruido de afuera; la categoría se elige en un segundo paso.\n\nUn aviso serio: la estafa favorita de esta plaza es el «te ganaste un premio» o la inversión mágica que dobla tu plata. Nunca pases datos bancarios ni claves por chat, por más amable que suene el desconocido. Si el mensaje entra en un grupo, avisa al admin y reporta el contenido desde el propio chat: cualquier persona puede hacerlo, sin drama.\n\n¿Tienes un grupo colombiano con buena energía? Publícalo en «Enviar un grupo». Completa la ficha, ponle una descripción honesta y deja que la gente de Cali, Barranquilla o Bucaramanga lo encuentre de una. Quien entra con expectativas claras se queda a charlar; quien entra a ciegas, no.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(5, 'country', 'Costa Rica', NULL, NULL, 'Un tico organiza casi todo su día desde WhatsApp: el futbolcito del sábado, la cita del taller y el bautizo de la sobrina. La conversa va con «pura vida» por delante y buen humor de sobra. El sábado arranca temprano, con el gallo pinto humeando en la mesa y el grupo de futbolcito pidiendo confirmar quiénes van. Y si llueve en la tarde, ni modo: el futbolcito se juega igual. Y cuando juegan Saprissa y Alajuelense, o la Sele en eliminatoria, el chat pasa a modo tormenta.\n\nPor estas tierras abundan los grupos de la iglesia, el futbolcito entre semana, la compra-venta del cantón y las comadres que comparten recetas y planes. Cuando busques en Grupos Hoy, marca Costa Rica y verás grupos de ticos y ticas, no de otra plaza. La categoría se elige aparte, así que puedes afinar de una vez.\n\nConsejo de presentarse: al entrar a un grupo nuevo, escribe corto. Tu nombre, de dónde eres y para qué entraste. Nada de discursos ni lluvia de imágenes de saludo. En los grupos ticos esa simpleza cae bien: la gente responde mejor a un mensaje claro que a una avalancha de buenos días. Y si el grupo tiene admin activo, lee la descripción antes de la primera pregunta.\n\n¿Tienes un grupo tico que merece más gente? La puerta está abierta: entra a «Enviar un grupo», escribe la descripción como se la contarías a un vecino y publícalo. No cuesta nada y le sirve a otra persona de tu cantón que anda buscando justo eso.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(6, 'country', 'Cuba', NULL, NULL, 'El parque con wifi funciona como sala de estar: la gente llega con el teléfono a media batería y se queda horas frente a la pantalla. En Cuba los datos se cuidan como el arroz, así que los grupos se usan con misión clara: ahorrar. Se comparte un enlace y se aprovecha; las fotos del mes se bajan en una sola sentada. Los mensajes van al grano, porque cada megabyte cuenta.\n\nLos grupos cubanos más comunes: los familiares de la isla, los que la conectan con la gente de afuera y los del barrio para avisos prácticos. El béisbol de la Serie Nacional tiene los suyos, con pasión de estadio. También están los que coordinan quién baja el Paquete Semanal, que ya es cultura nacional. Y los de chistes que corren más rápido que la guagua. En Grupos Hoy eliges Cuba en el filtro de país y ves los grupos pensados para la isla.\n\nEl consejo más útil es de datos: entra a los ajustes de WhatsApp y desactiva la descarga automática de fotos y videos con datos móviles. Guarda lo pesado para cuando encuentres wifi y responde en los grupos grandes con texto en vez de audios largos. El paquete dura el doble y nadie se pierde la charla.\n\nSi administras un grupo de la isla, publicarlo en «Enviar un grupo» lo pone al alcance de gente de La Habana a Santiago de Cuba. Un rato de trabajo y tu comunidad queda frente a mucha gente que anda buscando lo mismo que tu grupo ofrece.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(7, 'country', 'Ecuador', NULL, NULL, 'Hay dos cosas sagradas en un domingo ecuatoriano: el encebollado y el grupo de la familia. La sopa se come con el teléfono apoyado en la mesa, porque seguro aparece foto nueva del almuerzo. Cuando llega el clásico del Astillero, el grupo se divide entre Barcelona y Emelec, y ahí no hay neutral: hasta el más callado manda su meme. La semana sigue con los grupos del trabajo y del barrio, que no descansan ni con la llovizna de Quito.\n\nLa oferta ecuatoriana va de todo: fútbol de la LigaPro y de la Tri, compra-venta y grupos de la universidad para los deberes. También están los de la iglesia y los memes que viajan de la costa a la sierra. Grupos Hoy te deja filtrar por Ecuador: un clic y la lista queda limpia de grupos de otros países. Las categorías quedan a un toque de distancia.\n\nSobre los audios: en Ecuador se estilan largos y con cariño, pero no en todos lados caen igual. En un grupo de estudio o de trabajo, pregunta antes de mandar una charla de cinco minutos. Y si te llega un audio en mal momento, pide con confianza que te lo resuman en texto. Los acuerdos pequeños mantienen la conversa buena para todos.\n\n¿Tienes un grupo ecuatoriano? Deja el enlace en «Enviar un grupo» y escribe una descripción que se entienda a la primera. Así la gente de Guayaquil, Quito y Cuenca lo encuentra sin buscar de más. La Sierra y la Costa charlan distinto, pero en el mismo idioma: el de la buena conversa.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(8, 'country', 'El Salvador', NULL, NULL, 'Las pupusas del domingo saben mejor cuando el grupo las organiza: quién va por el atol, cuántas de queso y cuántas revueltas. En El Salvador la vida diaria pasa mucho por WhatsApp. La familia repartida entre San Salvador y el exterior coordina por chat. El chero del trabajo manda el meme del día y la iglesia avisa la hora del culto. Todo llega al teléfono, caliente y a tiempo.\n\nLos grupos salvadoreños más buscados: fútbol de la Selecta y de la liga local, compra-venta, universitarios, grupos de la parroquia y de memes bien cheros. En la compra-venta aparecen desde celulares hasta motos. En las playas, los grupos de surf de El Tunco y El Sunzal avisan cómo viene la ola del día. Si quieres encontrar grupos rápido, fija el país en El Salvador dentro de Grupos Hoy: la lista se queda con puro contenido local.\n\nCuidado con un clásico de esta plaza: los anuncios de cambio de dólares y de remesas «más baratas» dentro de grupos de compra-venta. Trata solo con gente conocida o con referencias reales. Si alguien te apura, te pide dinero por adelantado o te cambia de número a última hora, corta ahí mismo. Las operaciones buenas nunca tienen esa prisa. Y si el trato salió bien, deja la referencia escrita en el grupo: así proteges a los demás.\n\nY si tienes un grupo bien salvadoreño, compártelo. «Enviar un grupo» está abierto todo el año: llena los datos, escribe una descripción clara y otra gente de El Salvador lo encontrará sin dar vueltas. Ayuda también avisar en qué horarios se enciende la charla del grupo.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(9, 'country', 'España', NULL, NULL, 'La sobremesa española no termina en la mesa: sigue viva en el grupo del pueblo. Un café después de comer, el móvil en la mano y la charla continúa: las fiestas de agosto y el cartel de la verbena. Los grupos de padres del colegio y de vecinos de la comunidad llevan lo práctico del día: quién recoge a los niños y el ascensor estropeado. Y en agosto, cuando llega la fiesta del pueblo, el chat echa humo, vale.\n\n¿Qué se encuentra por aquí? Grupos de LaLiga y de fantasy del trabajo, compra-venta del barrio, rutas de senderismo por la sierra, grupos de recetas y memes de sobremesa. La página de España de Grupos Hoy reúne comunidades del país, sin mezclar resultados de otras zonas hispanas; después eliges el tema que te llame. Y por supuesto, las peñas futboleras: cada domingo tienen tema nuevo.\n\nTruco de supervivencia: el grupo del pueblo en fiestas patronales es una tormenta de audios a las tantas de la madrugada. No hace falta irse del grupo. Silencia ocho horas, o el fin de semana entero, y revísalo tranquilo al día siguiente con un café. Nadie se va a ofender contigo: todos están bailando en la verbena.\n\nSi llevas un grupo español con buena marcha, del barrio, de la peña o del curro, publícalo gratis en «Enviar un grupo». Una ficha honesta y el grupo queda listo para que lo encuentre gente de toda la comunidad. El formulario es corto y hace la mitad del trabajo.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(10, 'country', 'Guatemala', NULL, NULL, 'A las seis de la mañana, el grupo de la comunidad ya está activo. Avisan el bus que se quedó, el atol de elote que trae doña y el recordatorio de la escuela. En Guatemala el día se organiza por WhatsApp desde temprano. Da lo mismo el tráfico de la capital que el mercado del pueblo: el chat ya está prendido. Los grupos familiares cruzan el país entero, de Quetzaltenango a Petén, y en diciembre explotan con las posadas y los tamales colorados.\n\nLa oferta local es amplia: fútbol del campeonato local, la parroquia con sus horarios de misa, la compra-venta del municipio y la universidad con sus apuntes. Los memes bien chapines tienen su propio rincón. El mercado del pueblo también tiene los suyos: se manda la lista por chat y se recoge el pedido sin fila. En Grupos Hoy puedes activar el filtro de Guatemala y quedarte solo con grupos chapines; después eliges la categoría y afinas todavía más.\n\nConsejo de horarios: por acá mucha gente escribe antes de las siete, entre el bus y el primer café. Si esas notificaciones te rompen el sueño, silencia los grupos ruidosos al ir a dormir y quita el silencio al despertar. Nadie se molesta y tú descansas de verdad. El mensaje sigue ahí en la mañana, no se escapa.\n\n¿Llevas un grupo guatemalteco con gente activa? Publícalo desde «Enviar un grupo». La publicación es gratis, toma minutos y pone tu comunidad frente a gente de todo el país que anda buscando dónde charlar. Si el grupo es del interior, poner el nombre del municipio en la descripción ayuda un montón.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(11, 'country', 'Honduras', NULL, NULL, 'Honduras corre por WhatsApp: el trabajo, la iglesia y la familia compiten por el mismo chat, casi a diario. Antes de dar la primera mordida, la baleada ya está en la foto del grupo. La sopa de caracol de la costa se presume igual, con orgullo de todo el litoral atlántico. Los domingos, entre el partido de la Liga y el almuerzo en casa de la abuela, los mensajes no dejan de llegar. Y cuando llega el carnaval de La Ceiba, el grupo se llena de planes para el paseo.\n\nLos grupos catrachos favoritos: fútbol de la Liga Nacional y de la Sele, compra-venta, memes sin filtro. Las parroquias y los campus universitarios también tienen los suyos. Al filtrar por Honduras en Grupos Hoy, lo que ves son comunidades del país y nada más: primero el país, después el tema.\n\nCuidado con los «empleos fáciles» que llegan por chat: si te piden pagar un adelanto por el uniforme, un examen o una capacitación, es estafa. El trabajo de verdad no se paga por adelantado, no pide claves y no llega con enlaces raros. Avisa al admin y denuncia el mensaje desde el propio WhatsApp; cualquiera puede reportarlo en dos toques.\n\nY si tu grupo hondureño ya tiene su gente y sus reglas, dale visibilidad. Entra a «Enviar un grupo» y cuéntalo en dos líneas claras. La gente de Tegucigalpa, San Pedro Sula y La Ceiba lo encontrará sin tanto rodeo. Una descripción con sabor catracho gana confianza a primera vista.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(12, 'country', 'México', NULL, NULL, 'La familia mexicana rara vez vive junta en una sola ciudad. Está repartida entre Monterrey, Guadalajara y la capital, así que el grupo familiar funciona como la casa común. Ahí se acuerdan las posadas de diciembre, ahí aparece la foto de los tamales y ahí se arman los planes del próximo encuentro. Órale, que el grupo de la colonia tampoco se queda atrás: avisa del tandeo del agua y del torneo relámpago del domingo. Hasta el tianguis que se movió de calle se anuncia ahí.\n\nLos grupos mexicanos más buscados: los de la Liga MX con memes del fin de semana y la compra-venta de la colonia. Sigue la fila la universitaria, para apuntes y tareas, y la del trabajo. La de humor bien mexicano cierra con broche. Grupos Hoy tiene página propia para México: entras y todo lo que ves es de gente de aquí; después filtras por categoría y listo.\n\nPara los grupos de compra-venta, un cuidado que ahorra disgustos: entrega en lugar público y de día. La explanada o la tienda de la esquina funcionan perfecto. No compartas tu ubicación en vivo con desconocidos y desconfía del vendedor que apura con un «págame primero y mañana te lo llevo». La venta buena se ve, se toca y se paga en persona.\n\n¿Tu grupo mexicano no está en el directorio? Súbelo por «Enviar un grupo»: es gratis y en un rato queda a la vista de gente de todo el país. Una buena descripción ahorra preguntas y atrae justo a la gente que busca lo mismo que tu grupo.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(13, 'country', 'Nicaragua', NULL, NULL, 'Alguien sube la foto del nacatamal y en un rato el grupo de la familia está de fiesta. Así anda la charla nicaragüense: con comida por delante y buen humor siempre. La pregunta de siempre es quién hace el mejor vigorón, y el grupo la resuelve con foto y todo. Los grupos del barrio y del trabajo ordenan el día con avisos prácticos. Y en diciembre, con La Gritería, el chat va y viene con saludos y con el grito de siempre: «¿quién causa tanta alegría?».\n\nPor Nicaragua abundan los grupos de la iglesia y de béisbol (la pelota es pasión de casa). Siguen la compra-venta del barrio, la universidad y los memes pinoleros para el recreo. En los barrios, la cuadra entera se organiza por chat para apoyarse con el agua y la luz. Al escoger Nicaragua en Grupos Hoy, la lista se reduce a grupos del país. Filtras primero por la tierra y después por el tema que te guste.\n\nUn consejo que salva amistades: política y grupos familiares no se mezclan. El tema enciende la conversa más rápido que el fogón. Si las cosas se ponen pesadas, cambia de tema o silencia un rato. Los grupos duran años; la discusión de hoy se olvida, pero los rencores a veces no. Mejor cuidar la mesa que ganar la discusión.\n\nSi llevas un grupo pinolero con buena convivencia, publícalo en «Enviar un grupo»: una descripción clara, el enlace y nada más. Gente de Managua, León y Granada lo encontrará a la primera. Dos líneas honestas valen más que cualquier propaganda.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(14, 'country', 'Panamá', NULL, NULL, 'El sancocho del domingo se cocina primero en el grupo: quién lleva la yuca, quién el ñame, a qué hora se enciende la olla. En Panamá los planes se arman por WhatsApp a toda hora, entre el tranque de la vía y el viaje tranquilo en Metro. El saludo llega con su «¿qué xopa?» y la charla fluye con la calma de siempre, sin apuro pero sin pausa. En toda reunión panameña aparece el arroz con pollo, y el grupo se encarga de repartir quién lo trae.\n\nLos grupos panameños que nunca fallan: béisbol, fútbol de la selección y compra-venta con de todo. También la universidad, la iglesia y los memes con humor del patio. En Grupos Hoy eliges Panamá y el resto desaparece de la pantalla: queda puro grupo local, listo para filtrar por categoría.\n\nAtención con las rifas: por acá se rifan platos, electrodomésticos y hasta ayudas comunitarias, y casi todas son honestas. Pero si te piden depositar «para liberar tu premio», no es rifa: es estafa. Compra números solo en rifas de gente que conozcas o con respaldo claro dentro del grupo. La rifa buena nunca te cobra por ganar.\n\nY si el tuyo es un grupo panameño de los buenos, con charla sana y admin presente, mándalo por «Enviar un grupo». Sale gratis, toma poco y lo ve gente de la ciudad, del interior y hasta la que vive afuera. Si el grupo es de un pueblo, pon el nombre del pueblo en la descripción: así lo encuentra la gente del lugar.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(15, 'country', 'Paraguay', NULL, NULL, 'Tereré en una mano, teléfono en la otra: así camina la gente por Asunción. En Paraguay los grupos viven a su ritmo: tranquilos de día, llenos de planes al caer la tarde. El sábado hay fútbol, y el clásico entre Olimpia y Cerro Porteña divide familias enteras. En la mesa siempre hay chipa recién hecha; si no se sube foto, el almuerzo no cuenta. Y en Semana Santa, el horno de la abuela se prende y el grupo coordina quién trae el almidón de mandioca.\n\nLa oferta paraguaya va de la charla de fútbol a la compra-venta y a los grupos de la iglesia. Los universitarios y los memes que mezclan castellano y guaraní completan el cuadro, sin traducción de por medio. La compra-venta de acá se mueve rápido: a veces la moto ya se vendió el mismo día. En Grupos Hoy, con elegir Paraguay la lista queda con comunidades del país; la categoría se afina después con un clic.\n\nAlgo propio de esta plaza: muchos grupos conversan en jopara, esa mezcla de guaraní y castellano que se entiende sin estudiarla. Si una frase se te escapa, pregunta con confianza: la gente explica con gusto. Y si hablás guaraní, un saludo en la lengua abre cualquier grupo nuevo. Es la señal más clara de que llegaste con respeto.\n\nSi llevas un grupo paraguayo con gente activa, anótalo en «Enviar un grupo». No lleva nada y lo encuentra gente de Encarnación, Ciudad del Este y todo el país. Si tu grupo charla en guaraní, dilo en la descripción: la gente lo agradece antes de entrar.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(16, 'country', 'Perú', NULL, NULL, 'Nadie en Lima sabe cuánto durará el viaje a casa, así que la combi se sobrevive con el grupo abierto. En Perú el celular acompaña todo: la combi de vuelta, la cola del banco y el almuerzo del domingo con el cebiche de la abuela. El chifa del domingo también pelea el puesto: en algunas casas gana, en otras manda el cebiche. Y cuando juegan Universitario y Alianza, el clásico parte el chat en dos: ahí no hay neutrales, hay bandos.\n\nLos grupos peruanos más pedidos: fútbol de la liga peruana y de la blanquiroja, compra-venta y los universitarios para trabajos. Siguen los de la parroquia y los de comida: sí, existen grupos dedicados a comparar cebiches. Los memes criollos de la buena cierran la lista. En las alturas, los grupos del pueblo conectan Cusco, Puno y Arequipa en la misma charla. Al marcar Perú en Grupos Hoy, la lista queda con grupos peruanos de verdad, sin mezcla rara; el tema se elige después.\n\nUn aviso de esta plaza: la estafa del «paquete retenido» sigue viva. Llega el mensaje de que tu envío quedó retenido y hay que pagar un depósito para liberarlo. Ese aviso se disfraza con nombres de empresas de reparto conocidas, pero nadie serio cobra depósitos por chat. Si no esperas ningún paquete, bórralo. Si esperas uno, confirma con la empresa por su canal oficial. Nunca pagues antes de verificar nada.\n\nSi administras un grupo peruano con buena charla, ponlo en «Enviar un grupo»: sin costo y sin vueltas. La gente de Lima, Arequipa, Trujillo y más allá lo encontrará con lo justo. Y si el grupo charla de un solo tema, ponlo claro en la descripción: se agradece.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(17, 'country', 'Puerto Rico', NULL, NULL, 'Un apagón en la isla y el grupo de vecinos se convierte en centro de operaciones: quién tiene planta y dónde queda hielo. Después del temporal, el mismo grupo organiza quién ayuda a mover el árbol caído de la esquina. En Puerto Rico WhatsApp es herramienta de supervivencia y de fiesta a la vez. Se organizan las parrandas de diciembre y se debate el sofrito de cada familia con seriedad total. Los planes de playa se arman con el pronóstico del tiempo a mano.\n\nLos grupos boricuas más comunes: los de la familia, que cruzan la isla y la diáspora, y los del trabajo. Cada pueblo tiene el suyo, sin exagerar. Y los memes que solo un boricua entiende a la primera tampoco faltan. La página de Puerto Rico de Grupos Hoy reúne grupos de la isla: entras, filtras y listo.\n\nEl consejo más importante es de temporada: de junio a noviembre, ten el grupo de vecinos armado antes del huracán, no durante. Guarda los contactos clave también fuera del chat, en tu libreta de teléfonos. Cuando se caen la luz y los datos, el mensaje corto y el plan acordado valen más que cualquier app.\n\n¿Tienes un grupo boricua con buena vibra? Súbelo por «Enviar un grupo». La sección está abierta todo el año, no cuesta nada y ayuda a que gente de San Juan a Ponce lo encuentre cuando lo ande buscando. Y si es de un pueblo específico, nombra el pueblo en la ficha: aquí cada cual tiene su orgullo.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(18, 'country', 'República Dominicana', NULL, NULL, 'La pelota invernal manda en el chat dominicano desde octubre: Licey, Escogido y Águilas conviven en la misma conversación y a veces en la misma familia. En República Dominicana los grupos acompañan el día completo. El almuerzo, la bandera de siempre (arroz, habichuelas y pollo), se presume en foto. Los planes del finde se arman por chat y los apagones se comentan con humor, porque si no, uno se ahoga. La bachata del sábado se estrena en el grupo antes que en el colmado.\n\nLos grupos quisqueyanos favoritos: el béisbol de invierno y las Grandes Ligas, compra-venta, grupos de iglesia, de universidad y de memes dominicanos que no perdonan. Al poner República Dominicana en el filtro de Grupos Hoy, quedan solo comunidades del país; el tema se elige después.\n\nConsejo de convivencia: la pelota se siente con el corazón, y la broma entre Licey y Escogido es pan de cada día. Con las Águilas y el resto pasa igual. Ríete con gusto, pero mide el tono con gente que no conoces. Una broma mal puesta quema más que el sol del Malecón. La rivalidad se queda en el estadio y la amistad se queda en el chat.\n\nSi tu grupo dominicano tiene buena charla y admin presente todos los días, publícalo en «Enviar un grupo». El trámite sale gratis, lleva un momento y lo ve gente de Santo Domingo, Santiago y todo el Cibao. Y si es de peloteros, avisa el equipo en la descripción: la afición se encuentra sola.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(19, 'country', 'Uruguay', NULL, NULL, 'Se charla desde el desayuno hasta el asado: en Uruguay el mate y el grupo no conocen el descanso. El chat acompaña la siesta, la playa del verano y la sobremesa de los domingos. De día, el grupo del trabajo se alivia con chistes; de noche, el grupo de amigos arma la picada. Cuando juega el clásico entre Peñarol y Nacional, el grupo familiar se transforma en tribuna, con parientes en ambos lados, como manda la tradición. Y el chivito del viernes a la noche también se presume en foto, porque hay cosas que hay que mostrar.\n\nLos grupos orientales más buscados: fútbol local y la Sele, compra-venta y grupos de la facultad. Después vienen los del trabajo, los memes uruguayos de humor seco y los del barrio para organizarse. Al elegir Uruguay en Grupos Hoy, el directorio queda con puro grupo del país, sin resultados de la región mezclados.\n\nTruco criollo: para el asado del finde, usa la encuesta del grupo. Fecha, lugar y quién lleva el asado se votan en un minuto y no queda nadie afuera. Después la lista de compras se escribe en el mismo chat y nadie la pierde. La encuesta evita el «yo dije otra cosa» del lunes.\n\n¿Y tu grupo uruguayo? Si tiene gente activa y charla sana, «Enviar un grupo» lo publica gratis. Deja el enlace, una descripción corta y listo: lo van a encontrar montevideanos y gente del interior por igual. Si el grupo es de fútbol, aclará la tribuna en la descripción: acá se pregunta antes de entrar.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(20, 'country', 'Venezuela', NULL, NULL, 'Madruga, enciende la plancha para la arepa y mira el teléfono: así arranca el día de mucha gente en Venezuela. Los grupos familiares funcionan como la mesa de la casa, aunque cada quien esté en un pueblo distinto. En diciembre las hallacas vuelven a unir a todos: el grupo coordina quién trae la harina, quién guisa y quién envuelve. Esa semana también aparece el pan de jamón, con su reparto coordinado casa por casa. La hallaca se hace en grupo o no se hace.\n\nLos grupos venezolanos más buscados: fútbol de la Vinotinto y de las ligas, compra-venta, grupos de la universidad y de la iglesia. Los de cocina debaten el punto exacto de la carne mechada, y los de memes y plans de chamo no se quedan atrás. Si fijas Venezuela como país en Grupos Hoy, el directorio se queda con grupos de acá, de la familia y de los amigos de siempre.\n\nCuidado con el clásico moderno: el vendedor nuevo que pide pagar primero (por Zelle, pago móvil o lo que esté de moda) y desaparece. En los grupos de compra-venta, fíjate en la reputación: cuánto tiempo lleva la persona en el grupo y quién la recomienda. Y si la oferta es demasiado buena, desconfía: el que apura la venta suele tener sus razones. Cuando el vendedor insiste en seguir el trato en otra app, también es mala señal: lo decente se conversa donde está la gente.\n\n¿Tienes un grupo venezolano con buena energía? Publícalo por «Enviar un grupo»: sale gratis. Puede encontrarlo gente en Maracaibo, Valencia, Barquisimeto y también la que vive lejos de casa. Para esa gente, un grupo del país es un pedacito de la mesa familiar.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(21, 'city', 'Asunción', NULL, NULL, 'El calor de Asunción se pelea con el tereré: mientras el sol aprieta, la gente anda con el termo bajo el brazo y la guampa lista para compartir. La vida de grupo empieza por el barrio. En Villa Morra y en Carmelitas se juntan los cafés, las casas de cambio y las oficinas. En el Mercado 4 se consigue de todo y el regateo es parte del trámite. Para moverte no hay metro: son buses que se pagan en efectivo, y la Costanera se llena de gente a la tarde, cuando el río se pone naranja.\n\n¿Qué grupos se buscan por acá? Los del clásico entre Olimpia y Cerro Porteño, que reparte la familia en dos cada fin de semana. Los de compra-venta del barrio, donde se ofrece desde ropa hasta motos. Los de estudio de la UNA, que queda en San Lorenzo, y los de la Católica para las mismas batallas. Los de trabajo y turnos en la zona de Villa Morra. Y los de planes: la parrillada del domingo, el fútbol sala del martes, el club del barrio. Más arriba te dejamos la lista de grupos de Asunción para que elijas con calma.\n\nUn consejo de alguien de acá: para comprar o vender por grupo, queda en la entrada del Shopping del Sol o en una esquina con gente, nunca en una casa vacía. Si te ofrecen un celular nuevo a mitad de precio, desconfía: en Asunción las ofertas demasiado buenas casi siempre tienen truco. Y el dólar, mejor en las casas de cambio de Carmelitas, no por mensaje privado.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(22, 'city', 'Barcelona', NULL, NULL, 'Vivir en Barcelona es aprenderse la ciudad por barrios. Está Gràcia, con sus plazas donde la gente charla hasta la medianoche, y Sants, que vive a ritmo de estación. El metro te salva casi siempre y el bicing hace el resto. El vermut del mediodía es sagrado, las terrazas se llenan con el primer sol de marzo y, cuando llega la Mercè en septiembre, los castellers bajan a las plazas y la ciudad no duerme. En agosto medio barrio baja a la Barceloneta, y nadie se disculpa por llegar tarde.\n\nLos grupos que más se buscan aquí son de todo color: los debates del Barça, que se calientan solos cada partido; los de compra-venta y segunda mano entre quienes se mudan de distrito; los de la UB y la Pompeu Fabra, para apuntes y cervezas después de clase; y los de planes de finde, tipo caminata por Collserola o bajada al Garraf. La ciudad camina mucho y discute de todo con una birra en la mano. Ahí arriba tienes los grupos de Barcelona revisados uno por uno: entra, mira y quédate con los que te aporten algo.\n\nUn consejo local: en la L3 y en las plazas más turísticas, el móvil va en el bolsillo de adelante, no en el de atrás. Para cerrar tratos de segunda mano, queda en la puerta del mercado de Sant Antoni o en la entrada de los Encants: sitios con gente y luz. Y si alguien te pide dinero por adelantado para reservarte algo, esa es la señal para bloquear.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(23, 'city', 'Bogotá', NULL, NULL, 'El clima de Bogotá cambia de opinión tres veces al día. Llueve, sale sol, vuelve a llover, y todo el mundo sigue montado en la bici, porque los domingos la Séptima es de los ciclistas. La vida se reparte entre Chapinero, con sus cafés, La Candelaria, con sus balcones coloniales, y los cerros de Monserrate y Guadalupe, que miran la ciudad desde arriba. El TransMilenio la cruza por troncales rojas, y en hora pico se viaja pegado al de adelante. De madrugada, después de la rumba, el caldo de la esquina es obligatorio. Y a media tarde, las onces —chocolate con pan y queso— sostienen la jornada, como manda la tradición rola.\n\n¿Qué grupos se buscan en la capital? Los del clásico entre Millonarios y Santa Fe en El Campín, que divide la ciudad en dos. Los de compra-venta por barrios, de Chapinero a Suba. Los de la Nacional, los Andes y la Javeriana, para apuntes y proyectos. Los de trabajo y turnos. Y los de planes de fin de semana: mercado de pulgas en Usaquén, caminata al cerro, cine de arte. Arriba te dejamos los grupos de Bogotá ordenados y listos, con sus temas a la vista.\n\nConsejo de rolo: si vas a quedar con alguien del grupo, elige una estación troncal del TransMilenio o un parque con gente, nunca un sitio solo. A las siete de la mañana o a las cinco y media de la tarde el sistema va relleno, así que no fijes reuniones justo ahí. Y cuando llueva, avisa: aquí la lluvia retrasa hasta los planes mejor armados.', '2026-10-13 21:33:21')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(24, 'city', 'Buenos Aires', NULL, NULL, 'A las nueve de la mañana el subte D va relleno, y nadie se queja: se empuja. Esa es Buenos Aires a la hora pico. La ciudad se reparte en barrios con carácter propio. Palermo tiene cafés, plazas y perros con paseador; La Boca huele a pintura y a milonga; Almagro se vive alrededor de sus bares notables. Los colectivos cruzan todo con la SUBE, el tren Mitre te lleva a Tigre el fin de semana, y el café cortado con dos medialunas es el desayuno oficial, sin discusión.\n\n¿Qué se busca en grupos porteños? Fútbol antes que nada: la Bombonera y el Monumental tienen grupos propios, y el Superclásico parte el país en dos. También compra-venta de barrio, grupos de la UBA —la Facultad de Medicina y la de Filosofía son ciudades adentro de la ciudad—, trabajos y changas, y planes de finde: feria de Parque Centenario, paseo por el Rosedal, cine de la calle Corrientes. Cada barrio tiene su grupo, y los de Palermo no hablan de lo mismo que los de Constitución. Los grupos de Buenos Aires que ves arriba están ordenados para que encuentres el tuyo en dos minutos.\n\nUn consejo de pibe de acá: para comprar y vender, quedá en la boca del subte o en un café con mesas adentro, nunca en una esquina vacía. Desconfiá del que pide seña por transferencia antes de que veas el producto. Y si el precio es demasiado bueno, pensá dos veces: acá los golpes de suerte casi nunca son gratis.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(25, 'city', 'Cali', NULL, NULL, 'En Cali la salsa no se escucha: se respira. Suena en el bus, suena en el parque del barrio, y en las noches de Granada y de la Sexta se baila hasta que el cuerpo avise. La ciudad se recorre en el MIO, con San Antonio arriba, con su capilla y su mirador, y el Cristo Rey saludando desde la loma. El calor baja un poco al atardecer, el cholado con fruta es la moneda de la siesta, y en diciembre el alumbrado del río cambia la cara de la ciudad.\n\nLos grupos más buscados son los del fútbol: el América, con su banda roja, y el Deportivo Cali, que aunque juegue en Palmira sigue siendo de la casa. También se buscan grupos de salsa para principiantes, con rueda y todo; grupos de estudio de la Univalle, la Javeriana y la Icesi; compra-venta por los lados de la Galería Alameda; y grupos de trabajo y planes de finde, de paseo a Pance cuando sale el sol. Revisa más arriba: ahí están los grupos de Cali esperando gente con ganas de verdad.\n\nConsejo caleño de corazón: la salsa en Juanchito se baila al otro lado del río, así que arreglá con el grupo cómo vuelven antes de ir, que el taxi de madrugada cuesta su plata. Para comprar y vender, la Galería Alameda de mañana es la mejor cita: fruta fresca, gente amable y menos calor. Y si te invitan a una rueda de salsa, aceptá: nadie nace sabiendo, y aquí se aprende pisando.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(26, 'city', 'Caracas', NULL, NULL, 'Caracas vive encajonada entre el Ávila y el calor del valle, y esa montaña es el termómetro del ánimo: cuando amanece despejado, la ciudad entera le saca foto. En Los Palos Grandes se camina entre cafés y librerías. En El Hatillo se toma café con dulces y se camina despacio. En Sabana Grande se compra de todo, apurado. El metro sigue siendo lo más rápido para cruzar la ciudad, y el teleférico sube a Galipán, donde los de arriba venden fresas con crema con la niebla de fondo.\n\n¿Qué grupos se buscan acá? Los del Caracas Fútbol Club, los Rojos del Ávila, y los de la Vinotinto cada vez que juega. Los de compra-venta por zonas, porque avisar primero es regla. Los de la UCV, con su Ciudad Universitaria declarada patrimonio, y los de la Simón Bolívar para las mismas guerras de apuntes. Los de trabajo y turnos. Y los de planes de fin de semana, porque salir en grupo acá es más seguro y más divertido. La lista de grupos de Caracas está más arriba, lista para que te unas y participes.\n\nConsejo de un caraqueño de ley: para ir a Galipán o al teleférico, pregunta antes en el grupo cómo está la carretera o si hay mantenimiento, porque a veces cierran por niebla o por trabajos. En los grupos de compraventa, cuidado con los celulares sellados a precio de regalo: si no dejan ver el equipo en persona, chao. Y cuando llueve, resta tiempo a todo, que la ciudad se pone lenta.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(27, 'city', 'Ciudad de Guatemala', NULL, NULL, 'La capital de Guatemala no se ordena por barrios: se ordena por zonas. La 10 es la zona viva, de restaurantes y hoteles. El Cuatro Grados Norte, en la zona 4, llenó de cafés y galerías lo que antes era pura bodega. Y Paseo Cayalá, en la 15, es como un pueblito nuevo donde todo luce ordenado. El TransMetro de buses rojos alivia las calzadas, las camionetas multicolores siguen cargando la historia del transporte, y el centro guarda la plaza con la catedral y el Palacio, como siempre. El chapín camina rápido, pero siempre saluda.\n\n¿Qué grupos se buscan? Los del clásico nacional entre Comunicaciones y Municipal, Cremas contra Rojos, con el Mateo repleto cada vez que se ven las caras. También compra-venta de la zona 1 y de los mercados del centro. Grupos de la USAC y de la Landívar, para apuntes, proyectos y el clásico lío de horarios. Grupos de trabajo en las zonas 10 y 15, y grupos de planes de fin de semana: Antigua, los volcanes, el lago. Arriba, bien ordenados, están los grupos de Ciudad de Guatemala.\n\nUn consejo de acá: cuando juegan Cremas y Rojos, los grupos se llenan de memes en cinco minutos. Si la pelota no es lo tuyo, silencia ese día y listo, no pasa nada. En compraventa, quedá cerca de un punto conocido: el Obelisco o el Tikal Futura son referencias que todo el mundo ubica. Y el tráfico de las cinco es leyenda: avisa si vas tarde, que acá se entiende.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(28, 'city', 'Ciudad de México', NULL, NULL, 'Un chilango sabe leer el cielo gris, elegir la taquería de la esquina y encontrar el vagón del metro donde cabe uno más. La Roma y la Condesa concentran cafés, perros y terrazas; Coyoacán guarda su plaza con música los domingos; y el centro aguanta el ritmo de la ciudad entera entre el Zócalo y la Alameda. Entre el metro, el Metrobús y la Ecobici te mueves como puedas, porque el tráfico es un personaje más. Y el tianguis del barrio llega cada semana con su mantel de fruta, sin fallar.\n\n¿Qué grupos se buscan en el Valle? Los de fútbol, divididos entre las Águilas del América, la Máquina de Cruz Azul y los Pumas de la UNAM. Los de compra-venta por alcaldía, que la gente de la Roma no compra lo mismo que la de Iztapalapa. Los de la Universidad Nacional, para apuntes y prepa. Los de trabajo, freelancers y changas. Y los de planes: paseo en bici por Reforma un domingo, cine de arte, una pulquería del centro. Más arriba están los grupos de la Ciudad de México, revisados y ordenados por tema.\n\nConsejo de vecino de la Roma: los grupos del edificio funcionan cuando alguien modera. Pon reglas cortas y fijadas: solo temas del edificio, nada de cadenas ni ventas. Si nadie modera, en dos semanas el grupo es puro audio de doce minutos. Para el tianguis, lleva efectivo y llega temprano, porque lo bueno se va antes del mediodía. Y en la bici del domingo, agua y bloqueador, que el sol de acá no juega.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(29, 'city', 'Ciudad de Panamá', NULL, NULL, 'La Ciudad de Panamá se reconoce por sus torres: la zona bancaria de la Vía España creció hacia el cielo, y Punta Paitilla parece una ciudad de vidrio plantada al mar. En Bella Vista conviven el edificio antiguo y la torre nueva. La Cinta Costera corre junto a la bahía con ciclistas desde las cinco de la tarde, y el metro, esa Línea 1 que cambió la ciudad, conecta Albrook con el norte en minutos. En San Francisco queda el Multi, el mall donde tarde o temprano todo el mundo se cruza.\n\nLos grupos que más se buscan en esta ciudad son de trabajo: los bancos, las tiendas y los call centers de la zona bancaria publican turnos y vacantes. También moda y reventa —en el Multi se estrena y en Albrook se compra con calma—, grupos de la Universidad de Panamá y de la Tecnológica, grupos de fútbol para cuando juegan Tauro y Plaza Amador, y grupos para correr o pedalear la Cinta en manada. Y los de vecinos de Bella Vista y San Francisco, para lo del edificio y lo de la cuadra, que nunca sobran. Los grupos de Ciudad de Panamá que ves arriba están listos, con sus temas claros.\n\nConsejo capitalino a secas: a las cinco de la tarde la Vía España se para sola, así que organiza los encuentros fuera de esa franja. Para compraventa, las entradas de los malls son los puntos de encuentro clásicos: hay cámaras, gente y aire acondicionado. Y cuando la selección canalera juega, avisa antes de proponer planes: acá el país deja de trabajar un rato, de verdad.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(30, 'city', 'Córdoba', NULL, NULL, 'En Córdoba la siesta se respeta: la persiana del centro baja a la una y media y la ciudad se calla un rato. Después vuelve todo, con más calor y menos apuro. La vida de grupo se reparte por barrios con carácter. Güemes, con sus arcos y la feria del Paseo de las Artes los fines de semana. Nueva Córdoba, donde viven los estudiantes de la UNC, la universidad más antigua del país. Y la costanera del Suquía para las tardes de mate antes de la salida.\n\n¿Qué grupos se buscan? Los del clásico de Talleres, el Matador de Barrio Jardín, contra Belgrano, el Pirata de Alberdi, que parte la ciudad al medio. Los de cuarteto, porque cuando suena La Mona nadie se queda sentado. Los de compra-venta de barrio, los de la UNC para apuntes y mesas de examen, los de trabajo y turnos, y los de finde en las Sierras, que en verano Carlos Paz se llena y la ruta lo sabe. Más arriba te dejamos los grupos de Córdoba, con la onda local intacta.\n\nConsejo de cordobés de nacimiento: si mandás mensaje al grupo a las tres de la tarde, no esperés respuesta inmediata, acá la siesta se toma en serio. El fernet va con Coca, hielo y poca vergüenza. Y si vas a Carlos Paz el domingo, salí temprano, que la ruta se pone lenta desde las once. Para encontrarse, la plaza de Güemes o el Paseo de las Artes funcionan: los ubica todo el mundo.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(31, 'city', 'Guadalajara', NULL, NULL, 'Guadalajara huele a torta ahogada por la mañana y a mariachi por la noche. La Colonia Americana, con sus casonas convertidas en cafés y galerías, es el barrio del momento; la avenida Chapultepec concentra la marcha de jueves a domingo; y Tlaquepaque, con su Parián y sus talleres de artesanía, es el plan clásico de domingo. El Tren Ligero va a Zapopan sin sufrir el tráfico, el Mi Macro Periférico pelea la vuelta a la ciudad, y el tapatío defiende, con orgullo y argumentos, que aquí se come mejor que en la capital.\n\nLos grupos más buscados son de fútbol, claro: el clásico tapatío entre las Chivas del Guadalajara y los Zorros del Atlas divide familias enteras. También hay grupos de la UdeG para prepa y facultad, de compra-venta de colonia, de trabajo y vacantes, y de planes: Fiestas de Octubre, conciertos, y el mercado de Tonalá, que es de domingo y de madrugar. La lista de grupos de Guadalajara está más arriba, órale, dale una mirada y agarra los que te sirvan. Y si te gustan el fútbol y el mariachi, hay grupos que mezclan las dos pasiones.\n\nConsejo tapatío de manual: la torta ahogada se pide media si no aguantas el chile, y los valientes la piden bien ahogada. El mercado de Tonalá hay que agarrarlo temprano, porque al mediodía ya no queda nada bueno. Para quedar con gente del grupo, la Glorieta de Chapultepec o una estación del Tren Ligero son puntos que todos ubican. Y en el clásico tapatío, respeta la casa: aquí hasta el perro sabe de qué equipo es.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(32, 'city', 'La Habana', NULL, NULL, 'En La Habana el día se resuelve. El almendrón recorre la Calzada con su ruta fija y su tarifa pactada a gritos, la guagua va llena pero llega, y el Malecón sigue siendo el punto de encuentro más grande de la isla. En Vedado la vida pasa bajo los pórticos, en Habana Vieja los visitantes se mezclan con los vecinos, y la fila de Coppelia tiene sus propias reglas, que se aprenden rápido. La ciudad camina despacio, pero siempre está al tanto de lo que pasó anoche.\n\n¿Qué grupos se buscan acá? Los de béisbol de los Leones Azules de Industriales, que ponen el orgullo de la capital en cada serie. Los de compra, cambio y trueque, porque cuando algo aparece, el grupo se entera primero. Los de la Universidad de La Habana, para apuntes y avisos. Los del barrio, para resolver entre vecinos lo que se pueda resolver. Y los de planes: una ida a la playa del Este, un partido en el Latinoamericano. Más arriba están los grupos de La Habana que conseguimos revisar; entra a los que te sirvan.\n\nUn consejo de asere a asere: en WhatsApp, desactiva la descarga automática de fotos y videos. Los datos de ETECSA valen su precio y se acaban volando, sobre todo en grupos con gente que comparte de todo. Revisa los grupos cuando tengas wifi o saldo, y guarda el paquete para lo que importa. Y si vas a quedar con alguien, la esquina con luz y gente siempre es mejor que la esquina sola.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(33, 'city', 'La Paz', NULL, NULL, 'La Paz se viaja por el aire: la red de teleféricos urbanos más grande del mundo cruza entre El Alto y el cañón, y la gente se mueve mirando la ciudad desde arriba, como en un mirador permanente. El Prado marca el paso del centro. Sopocachi tiene su aire bohemio entre cafés y la calle Jaén, con sus museos apretaditos. La Zona Sur baja en temperatura y sube en comodidad. Todo esto pasa a más de tres mil quinientos metros de altura, donde el aire es fino y la salteña es comida de mañana.\n\n¿Qué grupos se buscan? Los del clásico paceño entre Bolívar, la Academia, y The Strongest, el Tigre. Los de compra-venta de los mercados y de la calle Eloy Salmón, donde se arma la electrónica. Los de la UMSA, para clases, apuntes y foros. Los de trabajo y turnos en la Zona Sur. Y los de planes: el show de las cholitas luchadoras en El Alto es una salida que hay que hacer con grupo. En la hora pico, el teleférico va lleno pero siempre con vista. Arriba te dejamos los grupos de La Paz con sus temas a la vista.\n\nConsejo de paceño: las salteñas se compran de mañana, con su jugo adentro; a la una de la tarde ya no queda. Se muerde la puntita, se sorbe el caldo y después se come, porque al revés te manchas toda la camisa. Si llegas de afuera, los primeros días camina lento y toma mate de coca: la altura no perdona de entrada, y el resto de la ciudad tampoco.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(34, 'city', 'Lima', NULL, NULL, 'El madrugón es un deporte limeño: salir a las seis para llegar a las ocho no es exageración, es calendario. La ciudad vive entre el mar de Miraflores y el bullicio del Cercado, con el Malecón para caminar mirando acantilados y Barranco para las noches de peña y arte. La combi con su cobrador gritando que suba, suba, es transporte y gimnasia al mismo tiempo. El Metropolitano alivia lo suyo, y en invierno la garúa pinta el cielo gris por semanas. La recompensa de siempre: un cebiche de mercado al mediodía.\n\n¿Qué grupos se buscan? Los de fútbol entre Alianza, la U y el Cristal, que en cada clásico llenan los grupos de memes y discusión sana. Los de compra-venta de barrio, porque la feria del mercado sigue siendo el centro comercial de la casa. Los de San Marcos, la primera universidad de América, y de la Católica. Los de trabajo y ofertas. Y los de planes de finde, de parapentes sobre el Malecón a una mesa de leche de tigre en el mercado. Más arriba están los grupos de Lima, causa, ordenados y listos.\n\nConsejo de limeño de pura cepa: el cebiche se come al mediodía. A las ocho de la noche los cebiches buenos ya cerraron, y el que te lo ofrezca de noche te está vendiendo otra cosa. Para quedar con gente del grupo, la puerta de un mercado o una estación del Metropolitano funcionan. Y en la combi, el celular en el bolsillo delantero, nunca en el de atrás.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(35, 'city', 'Madrid', NULL, NULL, 'Malasaña despierta tarde y Vallecas no duerme nunca: en esa frase cabe media Madrid. La ciudad se mueve en metro, una de las redes más grandes del mundo, y en Cercanías para quien vive más lejos. Los domingos, el Rastro tiende sus puestos por la Ribera de los Curtidores, y el centro huele a tortilla y a cañas. Las terrazas se llenan con el primer sol de marzo, la verbena de San Isidro convierte mayo en fiesta, y aquí se cena a las diez sin que nadie levante una ceja.\n\n¿Qué grupos se buscan en la capital? Los del derbi entre el Real Madrid y el Atlético, más los del Rayo de Vallecas, el equipo del barrio que nunca abandona al barrio. Los de compra-venta y mudanzas entre distritos. Los de la Complutense en Moncloa, para apuntes y birras después de clase. Los de curro, ofertas y turnos. Y los de planes de finde: tapas por la Cava Baja, un día de Casa de Campo, sofá y manta en enero. Los domingos de tapas por la Latina acaban siempre más tarde de lo previsto. Arriba tienes los grupos de Madrid, vale, revisa con calma y elige los tuyos.\n\nConsejo de madrileño de toda la vida: el Rastro es de domingo y de mediodía, y los carteristas también madrugan, así que el móvil va en el bolsillo de adelante. Para compraventa, queda en la puerta de un mercado o de un centro comercial, con gente alrededor. Y cuando quedes con alguien, avisa de línea de metro: aquí un «llego en diez» puede ser media hora de trayecto.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(36, 'city', 'Managua', NULL, NULL, 'Managua no usa nombres de calle: usa puntos de referencia. «De donde era el banco, dos cuadras al lago y una arriba»: así se llega a cualquier parte. El centro viejo quedó vacío después del terremoto del 72, y la ciudad se repartió en centros comerciales, malecones y puntos de encuentro. El Puerto Salvador Allende mira al lago Xolotlán, la laguna de Tiscapa guarda su mirador verde, los taxis se comparten y las direcciones se explican con las manos. Por eso el pin de WhatsApp vale acá más que cualquier dirección escrita.\n\n¿Qué grupos se buscan? Los de béisbol, porque aquí la pelota manda: cuando juegan los Indios del Bóer, la familia se divide con el rival de turno y la pelota se conversa todo el día. Los de compra-venta de los mercados, del Oriental para todo y del Huembes para la compra de siempre. Los de la UNI, la UNAN y la UCA, para apuntes y trabajos. Los de trabajo y turnos. Y los de la gritería del 7 de diciembre, cuando las casas se llenan de altares y la ciudad canta a la purísima. Los grupos de Managua que ves arriba están ahí para todo eso.\n\nConsejo pinolero: comparte tu ubicación en vivo por WhatsApp y pide la del otro. Acá mandar una dirección escrita casi nunca funciona, porque la gente se ubica por referencias, y las referencias cambian. «Del árbol que ya no está, dos cuadras al lago» es una dirección real y muy managua: pregunta bien antes de salir. Y para quedar, cualquier rotonda grande con letrero, que de eso está lleno el mapa.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(37, 'city', 'Medellín', NULL, NULL, 'La eterna primavera no es cuento: en Medellín se anda en camisa todo el año, con una lluvia corta de tarde que todo el mundo espera y nadie respeta. La ciudad se baja y se sube. La Comuna 13, con sus escaleras eléctricas y sus murales, es la cara del cambio. El Poblado es restaurante y rumba. Laureles es más paisa y más tranquilo, con la Setenta para tomarse algo. El metro es orgullo de todos, por ahora el único del país, y el Metrocable sube a las comunas colgando del aire, con la ciudad a los pies.\n\nLos grupos más buscados: los del clásico entre el DIM, el Poderoso, y el verde de Atlético Nacional, que llena el Atanasio Girardot cada vez. Los de compra-venta de barrio. Los de la UdeA y de la EAFIT, para apuntes y proyectos. Los de trabajo, vacantes y emprendimiento, que esta ciudad es una fábrica de ideas. Y los de planes: la Feria de las Flores con sus silleteros, el parque Arví arriba del cable, y las salidas de Laureles. De paso, la vista desde el cable vale la cola. Más arriba, parce, están los grupos de Medellín listos.\n\nConsejo paisa: para encontrarse con gente del grupo, queda en una estación del metro. Todas son puntos conocidos, con señalización y vigilancia. Lleva chaqueta ligera: subir a Arví te cambia el clima en media hora. Y si el plan es rumba en El Poblado, mira antes el último horario del metro, que cierra temprano; el regreso se arregla mejor con tiempo que con suerte.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(38, 'city', 'Monterrey', NULL, NULL, 'Lo primero que ves al llegar a Monterrey es el Cerro de la Silla: la montaña con silueta de montura que los regios miran como parte de la familia. La ciudad es trabajo y apuestas. Las torres del Valle Oriente, en San Pedro, crecen cada año. El Barrio Antiguo guarda la rumba de los fines de semana, y el centro guarda sus mercados de siempre, donde el cabrito se encarga desde temprano. El Metrorrey conecta lo justo, y el resto es camión o carro, porque el calor no invita a caminar.\n\n¿Qué grupos se buscan? Los del Clásico Regiomontano entre Rayados y Tigres, con el Tec y la UANL de por medio, que parte la casa en dos. Los de compra-venta de colonia. Los de estudio del Tec de Monterrey, que nació aquí, y de la UDEM. Los de trabajo y vacantes en las empresas del área, que de eso está llena la región. Y los de planes de finde: la ruta a la Cola de Caballo, el paseo a Santiago, la carne al asador en la casa de alguien del grupo. Arriba te dejamos los grupos de Monterrey, ordenados y con la info clara.\n\nConsejo regio: en julio y agosto el calor pasa de los cuarenta grados, así que organiza los planes del grupo de madrugada o de noche, o refúgiate en un mall, que para eso están. Para quedar, una estación del Metrorrey o la Macroplaza son puntos que todos ubican. Y con boletos de Rayados-Tigres a mitad de precio por canales raros, cuidado: la reventa tiene letra pequeña.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(39, 'city', 'Montevideo', NULL, NULL, 'La Rambla es la calle más larga y más querida de Montevideo: kilómetros de costa donde la gente camina, anda en patín y toma mate sin parar, con el termo bajo el brazo como si fuera parte del cuerpo. La Ciudad Vieja guarda la historia entre casonas y el mercado del Puerto, con su parrilla humeante. Pocitos tiene su playa y su vida de barrio. Y los domingos, la feria de Tristán Narvaja toma la calle con libros, herramientas y objetos con historia. Si llueve, hay tortas fritas: así de simple.\n\n¿Qué grupos se buscan? Los del clásico entre Nacional y Peñarol, que se juega en el Centenario, el estadio del primer Mundial de la historia. Los de compra-venta de las ferias barriales, de las que cada barrio tiene la suya. Los de la UDELAR, de todas las facultades. Los de trabajo y changas. Y los de mate y planes: la vuelta por la rambla al atardecer no se negocia. El mate va en ronda: se agradece y se devuelve, esa es la educación. Arriba están los grupos de Montevideo, bo, con sus temas a la vista y sin vueltas.\n\nConsejo de montevideano: anótate los días de feria de tu barrio —la de Pocitos es miércoles y sábado— y lleva efectivo, porque las ferias funcionan con billetes. En los grupos de compraventa, desconfiá del que pide pago adelantado y envío: quedá en la feria o en la rambla, con gente alrededor. Y en la salita de la casa, donde se recibe la visita con mate y facturas, también se arman los mejores planes de la semana.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(40, 'city', 'Panamá', NULL, NULL, 'El Casco Antiguo de Panamá se recorre a pie: techos de teja, iglesias de hace siglos y balcones con flores. En la plaza de la Catedral los vecinos toman su café, en la Plaza Francia los artistas ponen su puesto, y el mercado de mariscos, ahí cerquita, sirve el ceviche de la capital antes del mediodía. La calzada de Amador sale derecho al mar, con el Biomuseo de colores abriendo el camino, y frente a todo el paisaje cruza el Canal: en Miraflores los barcos suben y bajan las esclusas como una película lenta.\n\n¿Qué grupos se buscan en esta orilla? Los de la selección canalera, que para la gente de acá es una cita frente al televisor. Los de artesanos y compraventa del Casco. Los de vecinos de San Felipe, con los avisos del barrio a tiempo. Los de quienes trabajan en turismo y restaurantes, que el Casco amanece antes que la ciudad. Y los de planes: bici por la calzada al amanecer, una tarde de brisa en la punta. Más arriba te dejamos los grupos de Panamá, con su sabor del Casco y del canal.\n\nConsejo de acá, con historia incluida: si te ofrecen el famoso sombrero «panamá», pregunta de dónde viene. Nació en Ecuador y se hizo famoso cuando se vendía a los viajeros del Canal. Bonito igual, pero no es artesanía local. En compraventa del Casco, queda en la plaza de la Catedral o en el mercado de mariscos: puntos con movimiento de gente y fáciles de ubicar. Y camina con agua los días de sol, que el Casco tiene poquita sombra.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(41, 'city', 'Puebla', NULL, NULL, 'La talavera de Puebla se pinta a mano y se cuece dos veces, y las piezas buenas llevan la marca del taller al reverso. Ese detalle resume la ciudad: orgullosa de lo que hace bien. El centro histórico, patrimonio de la humanidad, se recorre entre casonas con azulejos. El Barrio de los Sapos junta anticuarios y cafés los fines de semana. Y a un lado queda Cholula, con su pirámide enorme, la más grande del mundo en volumen, y el Popocatépetl de fondo, que cuando se pone activo rocía ceniza sobre los autos.\n\n¿Qué grupos se buscan? Los de la Franja del Puebla, los camoteros, para sufrir y celebrar en compañía. Los de compra-venta de barrio. Los de la BUAP, para apuntes y trámites, y los de la UDLAP, allá en Cholula. Los de trabajo en las empresas de la zona, que la región es industrial y no lo esconde. Y los de planes: chiles en nogada en temporada, mole para la fiesta, cemitas el domingo. Cada fiesta en Puebla termina en mesa, y la mesa siempre es larga. Los grupos de Puebla están más arriba, con sus temas claritos.\n\nConsejo poblano: si compras talavera, mira que la pieza traiga el sello del taller; si no trae nada, es imitación. Los chiles en nogada tienen temporada, entre julio y septiembre más o menos, así que cuando en el grupo avisen que ya llegaron, ve esa misma semana. Y el 5 de mayo aquí sí se celebra a lo grande: desfile, fuertes de Loreto y Guadalupe, y la ciudad de gala.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(42, 'city', 'Quito', NULL, NULL, 'Quito te recibe a dos mil ochocientos cincuenta metros: la luz es limpia, el frío entra por el cuello aunque el sol esté brillando, y el cielo cambia de plan sin avisar. El centro histórico, de los primeros que la UNESCO declaró patrimonio, se camina entre iglesias barrocas y plazas con historia. La Floresta tiene cafés, murales y vida de barrio; la Mariscal es la zona de la marcha; y el Trole y la Ecovía llevan a la gente de norte a sur, con el metro ya dando sus vueltas. El helado de paila es postre de tradición: se bate en paila de bronce, con hielo y fruta.\n\n¿Qué grupos se buscan? Los de Liga de Quito y de Aucas, que cuando se ven las caras, la conversación se pone de colores. Los de compra-venta de los mercados, como la Iñaquito, donde la fruta llega de la sierra esa mañana. Los de la Católica y de la Central, para apuntes y horarios. Los de trabajo y turnos. Y los de planes: subir por el teleférico a Cruz Loma, las noches de la Mariscal, las caminatas del fin de semana. Más arriba están los grupos de Quito, de una, revísalos con calma.\n\nConsejo quiteño: guarda un abrigo en la mochila aunque amanezca soleado. Aquí graniza y sale sol en la misma tarde, y a esa altura el cuerpo siente cada escalera. Para quedar con gente del grupo, elige puntos del centro o una estación del Trole que todos ubiquen. Y si acabas de llegar, tómala con calma los primeros días: la altura cobra, pero se paga barato con vistas así.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(43, 'city', 'San José', NULL, NULL, 'A San José casi nadie la llama por su nombre: le dicen Chepe. El centro guarda casonas de colores de finales del siglo pasado, el Mercado Central huele a café y a culantro, y el Barrio Escalante se convirtió en el barrio de los restaurantes, con su paseo gastronómico para caminarlo de arriba abajo. En San Pedro vive la Universidad de Costa Rica, con sus estudiantes y sus sodas de siempre. El tren de cercanías volvió a correr, y la lluvia de la tarde, en temporada verde, es más puntual que muchos buses.\n\n¿Qué grupos se buscan? Los del Saprissa, el Monstruo del Morado, y los de la Sele cuando juega, que aquí hasta el que no mira fútbol mira a la Sele. Los de compra-venta de barrio y de las ferias. Los de la UCR, para apuntes, torneos y el lío sagrado de la matrícula. Los de trabajo y vacantes. Y los de planes: café en Escalante, una birra en el centro, el fútbol del sábado. Los grupos de San José están más arriba, mae, échales un ojo y agarra los que te sirvan.\n\nConsejo tico: cada barrio tiene su feria del agricultor el fin de semana, con fruta más fresca y más barata que en el súper, y se paga en efectivo. Si el grupo organiza algo al aire libre, que sea en la mañana: la lluvia de la tarde en temporada verde no falla. Y con el tráfico de la hora pico, avisa si vas tarde, que acá se entiende, pero se agradece.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(44, 'city', 'San Juan', NULL, NULL, 'La Placita de Santurce es dos lugares en uno: de día, mercado de frutas y verduras; de noche, la plaza más animada de la ciudad, con música en vivo y tragos en la mano. Así es San Juan. El Viejo San Juan camina sobre adoquines azulados que brillan con la lluvia, la Calle Loíza se llenó de restaurantes y murales, y el Condado vive entre torres y playa. El Tren Urbano te sirve si andas entre Río Piedras, Guaynabo y Bayamón, y la UPR alza su torre en Río Piedras, como siempre.\n\n¿Qué grupos se buscan? Los de los Cangrejeros en temporada de pelota invernal, que la pelota de invierno es herencia de casa. Los de compra-venta y reventa de todo. Los de la UPR de Río Piedras, para clases, apuntes y sobrevivir la matrícula. Los de trabajo, sobre todo en la zona hotelera. Y los de planes: salsa en vivo, una tarde de El Yunque, un día de playa en Piñones. En enero, la Calle San Sebastián llena Santurce de música: los grupos avisan dónde juntarse. Más arriba están los grupos de San Juan, boricua, listos para que te unas.\n\nConsejo de aquí: en temporada de huracanes, de junio a noviembre, los grupos de vecinos son un salvavidas: ahí corre la información de dónde hay luz, hielo y gasolina cuando algo pasa. Únete al de tu calle antes del verano. En la Placita, llega temprano si quieres mesa los viernes, que la noche se llena sola. Y mofongo: pídelo con calma, que llena más de lo que parece.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(45, 'city', 'San Salvador', NULL, NULL, 'San Salvador se vive en colonias. La Escalón y su Zona Rosa concentran restaurantes y oficinas; Santa Tecla, al pie del volcán, guarda las noches frescas y el arte; y el centro histórico, recién renovado, volvió a ser el lugar para caminar el domingo. Para cruzar la ciudad, camiones y buses hacen lo que pueden, el tráfico de las cinco es leyenda, y las pupusas del mediodía son la religión más practicada del país. Cuando la Selecta juega en el Cuscatlán, el estadio más grande de Centroamérica, la ciudad entera suena.\n\n¿Qué grupos se buscan? Los de fútbol y de la Selecta, para sufrir acompañado. Los de compra-venta, porque el trueque y la reventa mueven mucho. Los de la UES y de la UCA, para apuntes, proyectos y avisos del campus. Los de trabajo y vacantes. Los de vecinos de cada colonia, con alertas y avisos útiles. Y los de surf: las playas de La Libertad, El Tunco y El Zonte, quedan a un rato en carro, y los grupos de Surf City viven organizando subidas. Arriba te dejamos los grupos de San Salvador, maje, con todo ordenado.\n\nConsejo salvadoreño: en los grupos de compraventa aquí casi todo se mueve en dólares, y algunos aceptan Bitcoin además; manda solo lo que puedas permitirte perder, porque una transferencia no se devuelve. Para quedar, un punto conocido de la Escalón o una gasolinera con cámaras. Y las pupusas se piden por docena, revueltas, con su curtido aparte: eso lo aprende hasta el que acaba de llegar.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(46, 'city', 'Santiago', NULL, NULL, 'La once es casi religión en Santiago: pasadas las cinco de la tarde, la mesa se llena de pan, palta y té, y nadie la salta. La ciudad se mueve por su metro, con la Línea 1 cruzando el centro de punta a punta. La Vega Central surte la cocina de media región, y la persa Bío Bío es el imperio de lo de segunda, donde todo tiene dueño nuevo esperando. Los barrios tienen vocación: Bellavista rumba y arte, Barrio Italia junta cafés y diseño, y Ñuñoa es de ferias, familias y fútbol.\n\n¿Qué grupos se buscan? Los del clásico entre Colo-Colo, el Cacique, y la Universidad de Chile, la U, que parte el ambiente en dos. Los de compra-venta de las ferias y las persas, donde se regatea con una sonrisa. Los de la U de Chile y de la Católica, para apuntes y organizarse. Los de trabajo y empleos. Y los de planes: subir al San Cristóbal, tomarse un terremoto con helado adentro en la zona del Yungay, una vuelta en bici por el parque Forestal. Los grupos de Santiago están más arriba, po, elige los tuyos y avanza.\n\nConsejo santiaguino: en invierno hay días de preemergencia, cuando el aire se pone malo y cambian las reglas del día; revisa el estado ambiental antes de armar planes al aire libre. El taco de la tarde no perdona: para quedar, mejor una estación de metro del centro, que todos ubican. Y en la persa, regatea con buena onda, que es parte del precio.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(47, 'city', 'Santo Domingo', NULL, NULL, 'Al atardecer, el Malecón de Santo Domingo se llena de gente que va a mirar el mar, tomarse un frío y despejar la cabeza lejos del tráfico. La Zona Colonial guarda la catedral más antigua de América, y en sus calles nació la primera universidad del continente. El metro y el teleférico alivian el trayecto, Piantini y Naco concentran los malls y las torres nuevas, y el mangú con los tres golpes sostiene la semana desde el desayuno. La ciudad corre caliente, y la pelota de invierno le pone música.\n\n¿Qué grupos se buscan? Los del Licey y del Escogido, que dividen la capital entre azules y rojos cada temporada. Los de compra-venta y reventa, de todo y para todo. Los de la UASD, heredera de la primera universidad de América. Los de trabajo y ofertas, sobre todo en la zona colonial y los malls. Y los de planes: un día de playa en Boca Chica, una tarde colonial de domingo, una noche de salsa en la ciudad. Los domingos la Colonial es un plan completo: museos, cafés y música en las plazas. Más arriba están los grupos de Santo Domingo; qué lo qué, dale una mirada y únete a los que te muevan.\n\nConsejo dominicano: la pelota invernal va de noviembre a enero, y el Quisqueya se llena; si quieres seguir la temporada con la peña de tu equipo, únete a los grupos antes de que arranque. Para compraventa, queda en un punto con gente: la puerta de un mall de Piantini o una estación del metro. Y desconfía del teléfono sellado a mitad de precio: la caja vacía también pesa.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(48, 'city', 'Sevilla', NULL, NULL, 'Triana queda al otro lado del puente, y los trianeros te lo recuerdan cada vez que pueden. En Sevilla la vida se organiza alrededor del río y de las tapas: el pescaíto frito en una barra de la calle Betis, la cerámica pintada en los talleres de Triana, y Santa Cruz, que es un laberinto de callejones que en abril huele a azahar. La Giralda vigila el centro desde su torre, el metro y el tranvía hacen lo suyo, y la bicicleta pública, la Sevici, es de las más queridas de España. Aquí se sale de tapas y se vuelve tarde, sin culpa.\n\n¿Qué grupos se buscan? Los del gran derbi entre el Betis y el Sevilla, que esta ciudad lo vive como pocas. Los de compra-venta de barrio y de mudanza. Los de la Hispalense, para apuntes, exámenes y turnos de biblioteca. Los de trabajo y turnos. Y los de planes: la Semana Santa, la Feria de Abril, el tapeo del jueves, una ruta en bici por la Cartuja. Arriba están los grupos de Sevilla, illo, entra y elige con calma.\n\nConsejo hispalense de peso: en la Feria de Abril, la mayoría de las casetas son privadas y se entra de la mano de alguien de la familia o de un grupo de amigos. Tener grupo de caseta o de amigos es la llave de la Feria; sin él, te quedas mirando los farolillos desde afuera. Para compraventa, queda en la puerta de un bar con terraza de Triana o del centro. Y en el derbi, ubícate antes de escribir: aquí se nace bético o sevillista.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `entity_intros` (`id`, `entityType`, `entityName`, `customTitle`, `customHeroDesc`, `customIntro`, `updatedAt`) VALUES
(49, 'city', 'Tegucigalpa', NULL, NULL, 'Tegucigalpa trepa por los cerros, y cada colonia tiene su propio clima: en Palmira está la movida de oficinas y hoteles, en Lomas del Guijarro las casas con vista, y Colonia Kennedy aguanta el día a día de la mayoría. El Picacho corona la ciudad con su monumento y su mirador, el centro guarda la catedral y su parque, y el Mercado Mayoreo es el corazón comercial, donde se vende de todo y se negocia de todo. En invierno las lluvias caen serias y las calles bajas se llenan de agua; en verano, el cielo se limpia y el cerro se ve entero.\n\n¿Qué grupos se buscan? Los del clásico de la capital entre Olimpia y Motagua, el Ciclón Azul contra los albos, que pone la ciudad a hablar. Los de compra-venta de los mercados y de las colonias. Los de la UNAH, para apuntes, matrícula y torneos. Los de trabajo y vacantes, que Tegus y alrededores dan para mucho. Y los de vigilancia del barrio: en cada colonia hay un grupo de vecinos que comparte alertas, y es de lo más útil que existe. Arriba te dejamos los grupos de Tegucigalpa, ordenados por tema y listos.\n\nConsejo catracho: cuando llueva fuerte, pregunta en el grupo de la colonia qué calles están complicadas antes de salir; los que conocen la ciudad saben por dónde no hay que pasar. Para quedar por compraventa, elige una gasolinera o un centro comercial de la zona, con luz y movimiento. Y en el clásico Olimpia-Motagua, piensa dos veces lo que escribes: el admin del grupo también tiene equipo.', '2026-10-13 21:33:22')
ON DUPLICATE KEY UPDATE `entityType` = VALUES(`entityType`), `entityName` = VALUES(`entityName`), `customTitle` = VALUES(`customTitle`), `customHeroDesc` = VALUES(`customHeroDesc`), `customIntro` = VALUES(`customIntro`), `updatedAt` = VALUES(`updatedAt`);

-- ---------------------------------------------------------------------------
-- Table: group_feedback
