  UNIQUE KEY `uq_review_group_ip` (`groupId`,`ipHash`),
  KEY `idx_reviews_group` (`groupId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
